package com.nullchannel.android;
import static org.junit.Assert.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import org.json.*;
import android.content.*;
import android.telecom.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class NativeFinalizationTest {
    static class Store implements NativeCallAuth.BundleStore {String value;Store(JSONObject value){this.value=value.toString();}public String read(){return value;}public void write(String value){this.value=value;}public void remove(){value=null;}}
    JSONObject bundle(long access,long refresh,String token){return NativeCallSignaling.object("accessToken",token.repeat(64),"refreshToken",token.repeat(64),"accessExpiresAt",java.time.Instant.ofEpochMilli(access).toString(),"refreshExpiresAt",java.time.Instant.ofEpochMilli(refresh).toString(),"identityId","fixture-identity");}
    @Test public void healthyCredentialsDoNotRotateOrRequireJavascript()throws Exception{Store store=new Store(bundle(600000,86400000,"a"));assertEquals("a".repeat(64),NativeCallAuth.rotate(store,token->{fail("Unexpected renewal");return null;},false,0).getString("accessToken"));}
    @Test public void renewalWritesNewCredentialsAndPreservesGuestIdentity()throws Exception{Store store=new Store(bundle(1000,86400000,"a"));JSONObject rotated=bundle(600000,86400000,"b");rotated.put("identityId",JSONObject.NULL);JSONObject next=NativeCallAuth.rotate(store,token->{assertEquals("a".repeat(64),token);return rotated;},false,0);assertEquals("fixture-identity",next.getString("identityId"));assertEquals("b".repeat(64),new JSONObject(store.value).getString("refreshToken"));}
    @Test public void logoutDuringRenewalCannotResurrectCredentials()throws Exception{Store store=new Store(bundle(1000,86400000,"a"));try{NativeCallAuth.rotate(store,token->{store.remove();return bundle(600000,86400000,"b");},false,0);fail("Expected expiration");}catch(NativeCallAuth.Expired expected){assertNull(store.value);}}
    @Test public void expiredRefreshAndRevokedSessionsRemoveStoredCredentials()throws Exception{Store store=new Store(bundle(1000,2000,"a"));try{NativeCallAuth.rotate(store,token->null,false,3000);fail();}catch(NativeCallAuth.Expired expected){assertNull(store.value);}store=new Store(bundle(1000,86400000,"a"));try{NativeCallAuth.rotate(store,token->{throw new NativeCallAuth.Expired();},false,0);fail();}catch(NativeCallAuth.Expired expected){assertNull(store.value);}}
    @Test public void staleRevisionsDuplicateMessagesAndUnreadyPeersAreRejected()throws Exception{assertTrue(NativeSignalPolicy.revisionAllowed(1,2,true));assertFalse(NativeSignalPolicy.revisionAllowed(1,1,true));assertTrue(NativeSignalPolicy.revisionAllowed(2,2,false));assertFalse(NativeSignalPolicy.revisionAllowed(2,1,false));NativeSignalPolicy policy=new NativeSignalPolicy();policy.applied("one");assertTrue(policy.seen("one"));assertFalse(NativeSignalPolicy.bothReady(new JSONObject("{\"ready\":{\"caller\":true,\"callee\":false}}")));assertFalse(NativeSignalPolicy.invitationValid(1,2));}
    @Test public void telecomServiceRejectsUnknownCallsAndUsesSystemBindingPermission()throws Exception{Context context=RuntimeEnvironment.getApplication();android.content.pm.ServiceInfo service=context.getPackageManager().getServiceInfo(new ComponentName(context,NullChannelConnectionService.class),0);assertEquals("android.permission.BIND_TELECOM_CONNECTION_SERVICE",service.permission);NullChannelConnectionService calls=Robolectric.buildService(NullChannelConnectionService.class).create().get();android.os.Bundle extras=new android.os.Bundle();extras.putString("nc.callId","11111111-1111-4111-8111-111111111111");Connection result=calls.onCreateIncomingConnection(NativeTelecom.handle(context),new ConnectionRequest(NativeTelecom.handle(context),android.net.Uri.parse("nullchannel:anonymous"),extras));assertEquals(Connection.STATE_DISCONNECTED,result.getState());calls.onDestroy();}
    @Test public void forgedIncomingActivityIntentCannotAnswerOrCaptureMicrophone(){Context context=RuntimeEnvironment.getApplication();NativeIncomingCallActivity activity=Robolectric.buildActivity(NativeIncomingCallActivity.class,new Intent(context,NativeIncomingCallActivity.class).putExtra("callId","11111111-1111-4111-8111-111111111111").putExtra("callAction","answer")).create().get();assertTrue(activity.isFinishing());}
    @Test public void oneNativeMicrophoneLeaseRejectsOtherOwnersAndReleasesOnlyItsOwner(){assertTrue(NativeMicrophoneLease.claim("call:fixture-one"));assertFalse(NativeMicrophoneLease.claim("call:fixture-two"));NativeMicrophoneLease.release("call:fixture-two");assertFalse(NativeMicrophoneLease.claim("record:TEST1234"));NativeMicrophoneLease.release("call:fixture-one");assertTrue(NativeMicrophoneLease.claim("record:TEST1234"));NativeMicrophoneLease.clearRecording();assertTrue(NativeMicrophoneLease.claim("call:fixture-two"));NativeMicrophoneLease.release("call:fixture-two");}

}
